        { code: 'en', name: 'English', char: 'Aa' }, { code: 'hi', name: 'हिन्दी', char: 'अ' },
        { code: 'mr', name: 'मराठी', char: 'म' }, { code: 'gu', name: 'ગુજરાતી', char: 'અ' },
