                                        className="w-full py-1 bg-purple-100 text-purple-700 hover:bg-purple-200 dark:bg-purple-900/30 dark:text-purple-300 dark:hover:bg-purple-900/50 rounded text-xs font-bold transition-colors"
                                    >
                                        {t('use_this')}
